(()=>{"use strict";
const KEY="sanAntonioPublicCart_v1",cfg=window.SA_CONFIG||{},demo=new URLSearchParams(location.search).get("demo")==="1",catalog=demo?(window.SA_DEMO_CATALOG||[]):(window.SA_CATALOG||[]);let cart=read(),customer=null;
const $=(s,p=document)=>p.querySelector(s),$$=(s,p=document)=>[...p.querySelectorAll(s)],esc=s=>String(s??"").replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c])),detail=p=>[p.active&&p.active!==p.name?p.active:"",p.concentration,p.form,p.presentation].filter(Boolean).join(" · ");
function read(){try{const v=JSON.parse(localStorage.getItem(KEY));return Array.isArray(v)?v.filter(x=>x&&x.id&&Number(x.qty)>0):[]}catch{return[]}}
function save(){localStorage.setItem(KEY,JSON.stringify(cart));counts()}
function counts(){const n=cart.reduce((a,x)=>a+x.qty,0);$$("[data-cart-count]").forEach(e=>e.textContent=n)}
function toast(msg){const e=$("#toast");e.textContent=msg;e.classList.add("show");clearTimeout(toast.t);toast.t=setTimeout(()=>e.classList.remove("show"),2200)}
function initFilters(){function fill(id,label,values){$(id).innerHTML='<option value="">'+label+"</option>"+[...new Set(values.filter(Boolean))].sort((a,b)=>a.localeCompare(b,"es",{sensitivity:"base"})).map(x=>"<option>"+esc(x)+"</option>").join("")}fill("#labFilter","Todos los laboratorios",catalog.map(x=>x.lab));fill("#categoryFilter","Todas las categorías",catalog.map(x=>x.category))}
function products(){const q=$("#searchInput").value.trim().toLowerCase(),lab=$("#labFilter").value,cat=$("#categoryFilter").value,direction=$("#sortOrder").value==="za"?-1:1,list=catalog.filter(x=>(!q||[x.name,x.active,x.concentration,x.lab,x.form,x.presentation].join(" ").toLowerCase().includes(q))&&(!lab||x.lab===lab)&&(!cat||x.category===cat)).sort((a,b)=>direction*a.name.localeCompare(b.name,"es",{sensitivity:"base",numeric:true}));$("#productGrid").innerHTML=list.map(p=>'<article class="product-card"><div class="product-thumb">'+(p.image?'<img src="'+esc(p.image)+'" alt="'+esc(p.name)+'" loading="lazy" width="640" height="420">':'<span aria-hidden="true">SA</span>')+'</div><div class="product-card-body"><div class="product-lab">'+esc(p.lab)+'</div><h3>'+esc(p.name)+'</h3>'+(detail(p)?'<div class="product-details">'+esc(detail(p))+'</div>':'')+(p.description?'<p class="product-description">'+esc(p.description)+'</p>':'')+'<button class="btn btn-primary" data-add="'+esc(p.id)+'">Agregar al pedido</button></div></article>').join("");$("#catalogEmpty").hidden=list.length>0;$$("[data-add]").forEach(b=>b.onclick=()=>add(b.dataset.add))}
function add(id,qty=1){const p=catalog.find(x=>x.id===id);if(!p)throw new Error("Producto no disponible");const f=cart.find(x=>x.id===id);if(f)f.qty=Math.min(9999,f.qty+qty);else cart.push({id:p.id,name:p.name,presentation:p.presentation,details:detail(p),qty});save();toast("Producto agregado al pedido")}
function change(id,d){const x=cart.find(v=>v.id===id);if(x){x.qty=Math.max(1,x.qty+d);save();renderCart()}}
function renderCart(){const e=$("#cartItems");e.innerHTML=cart.map(x=>'<article class="cart-item"><div><h3>'+esc(x.name)+"</h3><small>"+esc(x.details||x.presentation||"")+'</small></div><div class="qty"><button data-minus="'+esc(x.id)+'" aria-label="Disminuir cantidad">−</button><input data-qty="'+esc(x.id)+'" type="number" min="1" max="9999" value="'+x.qty+'" inputmode="numeric" aria-label="Cantidad"><button data-plus="'+esc(x.id)+'" aria-label="Aumentar cantidad">+</button></div><button class="remove" data-remove="'+esc(x.id)+'">Eliminar</button></article>').join("");$("#cartEmpty").hidden=cart.length>0;$("#cartActions").hidden=!cart.length;$$("[data-minus]").forEach(b=>b.onclick=()=>change(b.dataset.minus,-1));$$("[data-plus]").forEach(b=>b.onclick=()=>change(b.dataset.plus,1));$$("[data-remove]").forEach(b=>b.onclick=()=>{cart=cart.filter(x=>x.id!==b.dataset.remove);save();renderCart()});$$("[data-qty]").forEach(i=>i.onchange=()=>{const x=cart.find(v=>v.id===i.dataset.qty);x.qty=Math.max(1,Math.min(9999,parseInt(i.value,10)||1));save();renderCart()})}
function show(step){$$("[data-step]").forEach(s=>s.hidden=s.dataset.step!==step);const m={cart:["Paso 1 de 3","Mi pedido","33.333%"],form:["Paso 2 de 3","Datos de la farmacia","66.666%"],review:["Paso 3 de 3","Revisar solicitud","100%"]}[step];$("#stepLabel").textContent=m[0];$("#dialogTitle").textContent=m[1];$("#progressBar").style.width=m[2];if(step==="cart")renderCart();if(step==="form")$("#compactSummary").innerHTML="<strong>Resumen:</strong> "+cart.map(x=>esc(x.name)+(x.details?" ("+esc(x.details)+")":"")+" × "+x.qty).join(" · ");if(step==="review")review();$(".dialog-body").scrollTop=0}
function open(){show("cart");if(!$("#orderDialog").open)$("#orderDialog").showModal()}
function validate(form){const d=Object.fromEntries(new FormData(form));d.observations=(d.observations||"").trim();d.phone=(d.phone||"").replace(/[\s()-]/g,"");if(!d.pharmacy.trim()||!d.responsible.trim()||!d.address.trim()||!d.phone)return[null,"Completa todos los campos obligatorios."];if(!/^\+?[0-9]{7,15}$/.test(d.phone))return[null,"Ingresa un número válido (7 a 15 dígitos)."];if(!cart.length)return[null,"Agrega al menos un producto."];return[d,""]}
function review(){const o=customer.observations?'<p><strong>Observaciones:</strong> '+esc(customer.observations)+"</p>":"";$("#reviewContent").innerHTML='<div class="review-block"><h3>Datos del cliente</h3><p><strong>Farmacia:</strong> '+esc(customer.pharmacy)+"</p><p><strong>Responsable:</strong> "+esc(customer.responsible)+"</p><p><strong>Teléfono:</strong> "+esc(customer.phone)+"</p><p><strong>Dirección/Zona:</strong> "+esc(customer.address)+"</p>"+o+'</div><div class="review-block"><h3>Pedido</h3><ul class="review-products">'+cart.map(x=>"<li>"+esc(x.name)+" — "+x.qty+" "+(x.qty===1?"unidad":"unidades")+(x.details?" <small>("+esc(x.details)+")</small>":"")+"</li>").join("")+"</ul></div>";$("#configWarning").hidden=!!String(cfg.whatsappNumber||"").trim()}
function buildMessage(){const a=["NUEVA SOLICITUD DE PEDIDO","DISTRIBUIDORA SAN ANTONIO","","Farmacia: "+customer.pharmacy,"Responsable: "+customer.responsible,"Teléfono: "+customer.phone,"Dirección/Zona: "+customer.address,"","PEDIDO:","",...cart.map(x=>"• "+x.name+(x.details?" ("+x.details+")":"")+" — "+x.qty+" "+(x.qty===1?"unidad":"unidades"))];if(customer.observations)a.push("","Observaciones: "+customer.observations);a.push("","Solicito confirmación de disponibilidad.");return a.join("\n")}
async function send(){const msg=buildMessage(),n=String(cfg.whatsappNumber||"").replace(/\D/g,"");if(!n){try{await navigator.clipboard.writeText(msg);toast("Mensaje copiado. Falta configurar el WhatsApp.")}catch{toast("Falta configurar el WhatsApp corporativo.")}return}window.open("https://wa.me/"+n+"?text="+encodeURIComponent(msg),"_blank","noopener")}
function contact(){const vals=[["WhatsApp / teléfono",cfg.phone||cfg.whatsappNumber],["Dirección",cfg.address],["Correo",cfg.email],["Horarios",cfg.hours]];$("#contactDetails").innerHTML=vals.map(([a,b])=>"<div><dt>"+a+"</dt><dd>"+esc(b||"Por confirmar")+"</dd></div>").join("");const b=$("#generalWhatsapp"),n=String(cfg.whatsappNumber||"").replace(/\D/g,"");if(n){b.disabled=false;b.textContent="Consultar por WhatsApp";b.onclick=()=>window.open("https://wa.me/"+n,"_blank","noopener")}}
$("#menuBtn").onclick=()=>{const n=$("#mainNav"),o=n.classList.toggle("open");$("#menuBtn").setAttribute("aria-expanded",o)};$$('#mainNav a').forEach(a=>a.onclick=()=>{$("#mainNav").classList.remove("open");$("#menuBtn").setAttribute("aria-expanded","false")});$$("[data-open-cart]").forEach(b=>b.onclick=open);$$("[data-close-dialog]").forEach(b=>b.onclick=()=>$("#orderDialog").close());$("#orderDialog").addEventListener("click",e=>{if(e.target===$("#orderDialog"))$("#orderDialog").close()});$("#searchInput").oninput=products;$("#labFilter").onchange=products;$("#categoryFilter").onchange=products;$("#sortOrder").onchange=products;$("#clearCart").onclick=()=>{if(confirm("¿Vaciar todos los productos del pedido?")){cart=[];save();renderCart()}};$("#toForm").onclick=()=>show("form");$$("[data-back-cart]").forEach(b=>b.onclick=()=>show("cart"));$$("[data-edit-data]").forEach(b=>b.onclick=()=>show("form"));$("#customerForm").onsubmit=e=>{e.preventDefault();const[d,error]=validate(e.currentTarget);$("#formError").textContent=error;if(d){customer=d;show("review")}};$("#sendWhatsapp").onclick=send;
if(demo)$("#demoAlert").hidden=false;initFilters();products();counts();contact();if("serviceWorker" in navigator)addEventListener("load",async()=>{try{const regs=await navigator.serviceWorker.getRegistrations();await Promise.all(regs.map(r=>r.unregister()));if("caches" in window){const keys=await caches.keys();await Promise.all(keys.filter(k=>k.startsWith("san-antonio-web-")).map(k=>caches.delete(k)))}}catch(e){}});
const mc=document.modelContext;if(mc?.registerTool)Promise.resolve(mc.registerTool({name:"stage_order_items",title:"Preparar productos del pedido",description:"Agrega productos visibles del catálogo al pedido.",inputSchema:{type:"object",properties:{items:{type:"array",items:{type:"object",properties:{id:{type:"string"},quantity:{type:"integer",minimum:1,maximum:9999}},required:["id","quantity"],additionalProperties:false}}},required:["items"],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:({items})=>{items.forEach(i=>add(i.id,i.quantity));renderCart();return{itemCount:cart.length,totalUnits:cart.reduce((n,x)=>n+x.qty,0)}}})).catch(()=>{});
})();
